#include <net/bluetooth/bluetooth.h>
#include <net/bluetooth/rfcomm.h>

int get_rfcomm_address(struct socket *sock, struct sockaddr *addr, int *len, int peer) {
    struct sockaddr_rc *saddr = (struct sockaddr_rc *)addr;

    saddr->rc_family = AF_BLUETOOTH;
    if (peer) {
        if (sock->sk->sk_state != TCP_ESTABLISHED)
            return -EINVAL;
        bacpy(&saddr->rc_addr, &bt_sk(sock->sk)->dst);
    } else {
        bacpy(&saddr->rc_addr, &bt_sk(sock->sk)->src);
    }

    saddr->rc_channel = bt_sk(sock->sk)->channel;
    *len = sizeof(struct sockaddr_rc);
    return 0;
}

int get_rfcomm_address(struct socket *sock, struct sockaddr *addr, int *len, int peer) {
