#include <linux/socket.h>
#include <linux/bluetooth.h>

int get_rfcomm_sockaddr(struct socket *sock, struct sockaddr *addr, int *len, int peer) {
    struct sockaddr_rc *sa_rc = (struct sockaddr_rc *)addr;
    struct sock *sk = sock->sk;

    sa_rc->rc_family = AF_BLUETOOTH;

    if (peer) {
        bacpy(&sa_rc->rc_bdaddr, &bt_sk(sk)->dst);
        sa_rc->rc_channel = bt_sk(sk)->dst_chan;
    } else {
        bacpy(&sa_rc->rc_bdaddr, &bt_sk(sk)->src);
        sa_rc->rc_channel = bt_sk(sk)->src_chan;
    }

    *len = sizeof(struct sockaddr_rc);
    return 0;
}
